# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_rows

def _shift(worker, weekday, start, finish):
    return Shift(worker, weekday, Span(start, finish))

class TimesheetRowTests(unittest.TestCase):
    def test_busiest_first_by_hours(self):
        shifts = [
            _shift("Odell", "mon", 540, 900),
            _shift("Brisa", "mon", 540, 1080),
        ]
        busy, quiet = timesheet_rows(shifts)
        self.assertEqual(busy, "Brisa: 1 shift, 9.0 hours")
        self.assertEqual(quiet, "Odell: 1 shift, 6.0 hours")

    def test_counts_every_shift(self):
        shifts = [
            _shift("Quill", "tue", 540, 600),
            _shift("Quill", "wed", 540, 600),
        ]
        expected = "Quill: 2 shifts, 2.0 hours"
        self.assertEqual(timesheet_rows(shifts), [expected])

    def test_overlaps_for_one_worker_not_merged(self):
        shifts = [
            _shift("Brisa", "mon", 540, 720),
            _shift("Brisa", "mon", 660, 780),
        ]
        expected = "Brisa: 2 shifts, 5.0 hours"
        self.assertEqual(timesheet_rows(shifts), [expected])

    def test_quarter_hour_rounds_half_up(self):
        shifts = [_shift("Brisa", "fri", 540, 555)]
        expected = "Brisa: 1 shift, 0.3 hours"
        self.assertEqual(timesheet_rows(shifts), [expected])

    def test_ties_sorted_by_name(self):
        shifts = [
            _shift("Quill", "mon", 540, 600),
            _shift("Brisa", "mon", 540, 600),
        ]
        first, last = timesheet_rows(shifts)
        self.assertEqual(first, "Brisa: 1 shift, 1.0 hours")
        self.assertEqual(last, "Quill: 1 shift, 1.0 hours")

class TimesheetErrorTests(unittest.TestCase):
    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker_raises(self):
        shifts = [_shift("  ", "mon", 540, 600)]
        with self.assertRaises(ValueError):
            timesheet_rows(shifts)
